import React, { useState } from 'react';

export default function Product() {
    let [product, setProduct] = useState({
        id: 1,
        title: "Fjallraven - Foldsack No. 1 Backpack, Fits 15 Laptops",
        price: 109.95,
        image: "https://fakestoreapi.com/img/81fPKd-2AYL._AC_SL1500_.jpg", // Fixed image URL (removed spaces and added underscores)
        description: "Your perfect pack for everyday use and walks in the forest. Stash your laptop (up to 15 inches) in the padded sleeve, your everyday",
        rating: 3.9,
        qty: 1,
        brand: "Gucci"
    });

    let { image, brand, price, qty } = product;

    function handleinc() {
        setProduct(function (item) {
            return { ...item, qty: item.qty + 1 };
        });
    }

    function handledec() {
        setProduct(function (item) {
            return { ...item, qty: item.qty > 1 ? item.qty - 1 : 1 };
        });
    }

    return (
        <>
        <nav>reactevent</nav>
            <section className="container-fluid mt-3">
                <div className="col-3 m-auto">
                    <div className="card">
                        <div className="card-header">
                            <img src={image} alt="product" className="img-fluid" />
                        </div>
                        <div className="card-body text-center">
                            <h2>{brand}</h2>
                            <h3>&#8377;{Math.trunc(price)}</h3>
                            <h2>
                                <i
                                    className='fa fa-minus-circle me-2 text-danger'
                                    onClick={handledec}
                                    style={{ cursor: 'pointer' }}
                                ></i>
                                {qty}
                                <i
                                    className='fa fa-plus-circle ms-2 text-success'
                                    onClick={handleinc}
                                    style={{ cursor: 'pointer' }}
                                ></i>
                            </h2>
                        </div>
                    </div>
                </div>
            </section>
        </>
    );
}
